// Shared logic for the 5 HOD-Recommended-Transfer reviewer stages
// (HR Director → Supervisor → District HR → District HOD → PS). Each stage's
// component supplies its own `stageConfig` (see the per-stage .vue files
// under lesotho/components/transfers/) and combines this mixin with
// generalMixin (for loggedInStaff) and processQuestionnaire (for the actual
// submit-to-backend call).
//
// ── Backend contract (for whoever implements the workflow files) ──────────
// Each stage POSTs via processFHIR() to /fhir/QuestionnaireResponse with:
//   - questionnaire: this.stageConfig.questionnaireUrl (see REVIEWER_STAGES)
//   - flat body fields (same convention as createHODTransferRecommendationWorkflow.js):
//       reviewDecision:  "approved" | "rejected"    (review-status-valueset)
//       comments: string
//       date: "YYYY-MM-DD"
//       request: "<transfer Basic id>"
//       hodRecommendedTransferReference: "Basic/<transfer id>"
//   NOTE: deliberately not named "status" — processFHIR() (processQuestionnaire
//   mixin, shared core code) always sets this.fhir.status = "completed" for
//   the FHIR QuestionnaireResponse's own resource status, which would
//   otherwise silently overwrite the review decision before it's POSTed.
//   - the transfer id is also present as ?request=<id> in the query string
//     (both the task link and processFHIR's querystring passthrough carry it)
// Expected server-side responsibilities (not built here — UI only):
//   - reject if the transfer's current request-status isn't this stage's
//     "under...review" code (sequence enforcement)
//   - reject if the requester isn't the authorized reviewer for this stage
//   - create the Basic/review-hod-recommended-transfer-profile record
//   - advance the transfer's request-status to the next stage (or, for PS,
//     set the terminal "approved"/"rejected" status)
//   - create the next stage's reviewer Task(s)

const REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/review-hod-recommended-transfer-profile";
const TRANSFER_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/hod-recommended-transfer-profile";

const REVIEWER_STAGES = [
  {
    code: "directorhr",
    label: "HR Director",
    status: "underhrdirectorreview",
    icon: "mdi-briefcase-account",
  },
  {
    code: "supervisor",
    label: "Supervisor",
    status: "undersupervisorreview",
    icon: "mdi-account-tie",
  },
  {
    code: "districthr",
    label: "District HR",
    status: "underdistricthrreview",
    icon: "mdi-account-group",
  },
  {
    code: "districthod",
    label: "District HOD",
    status: "underdistricthodreview",
    icon: "mdi-account-star",
  },
  {
    code: "ps",
    label: "PS",
    status: "underpsreview",
    icon: "mdi-shield-account",
  },
  {
    code: "hoddirector",
    label: "HOD Director — Applies Transfer",
    status: "psapproved",
    icon: "mdi-check-decagram",
    // Not a peer review stage — there's no ReviewHODRecommendedTransfer
    // record for this step. It's the HOD Director physically applying the
    // transfer (hod-apply-transfer.vue), derived straight from the main
    // transfer's own status rather than from `reviews`.
    terminal: true,
  },
];

export default {
  props: ["queries"],

  data() {
    return {
      loading: true,
      checkingAccess: true,
      error: null,
      isAuthorized: false,
      saving: false,
      formSubmitted: false,

      transferId: null,
      staffPractitionerRef: null,
      staffName: "",

      transfer: {
        plannedTransferDate: null,
        transferReason: "",
        status: null,
        statusDisplay: "",
        eventDate: null,
        requesterName: "",
      },
      currentPosition: {},
      destinationPosition: {},
      reviews: [],

      form: {
        status: null,
        comments: "",
        date: new Date().toISOString().substr(0, 10),
      },
      reviewStatusOptions: [
        { text: "Approve", value: "approved" },
        { text: "Reject", value: "rejected" },
      ],

      afterSaveMessage: "",
      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    myExistingReview() {
      return (
        this.reviews.find(
          (r) => r.reviewerCode === this.stageConfig.reviewerCode,
        ) || null
      );
    },

    myTurn() {
      return (
        this.isAuthorized &&
        !this.myExistingReview &&
        this.transfer.status === this.stageConfig.expectedStatus
      );
    },

    currentStageCode() {
      return (
        REVIEWER_STAGES.find((s) => s.status === this.transfer.status)?.code ||
        null
      );
    },

    isPastMyStage() {
      const myIndex = REVIEWER_STAGES.findIndex(
        (s) => s.code === this.stageConfig.reviewerCode,
      );
      const currentIndex = REVIEWER_STAGES.findIndex(
        (s) => s.code === this.currentStageCode,
      );
      if (currentIndex === -1) return true; // terminal (approved/rejected/cancelled)
      return currentIndex > myIndex;
    },

    // True once the HOD Director has actually applied the transfer — i.e.
    // the transfer moved on from "psapproved" to some terminal status that
    // isn't a rejection/cancellation and isn't still "under...review".
    // Deliberately doesn't hardcode the eventual terminal status code (e.g.
    // "transferred"), since that's decided by the backend workflow.
    isTransferApplied() {
      const status = this.transfer.status || "";
      if (!status) return false;
      if (status === "psapproved") return false;
      if (status.includes("rejected") || status === "cancelled") return false;
      if (status.includes("review")) return false;
      return true;
    },

    timeline() {
      return REVIEWER_STAGES.map((stage) => {
        if (stage.terminal) {
          // No ReviewHODRecommendedTransfer record backs this step — derive
          // it from the transfer's own status instead of `reviews`.
          return {
            ...stage,
            review: this.isTransferApplied
              ? {
                  status: "approved",
                  statusDisplay: "Transfer Applied",
                  reviewerName: "HOD Director",
                  date: this.transfer.lastUpdated,
                  comments: "",
                }
              : null,
            isCurrent: this.currentStageCode === stage.code,
          };
        }
        return {
          ...stage,
          review: this.reviews.find((r) => r.reviewerCode === stage.code) || null,
          isCurrent: this.currentStageCode === stage.code,
        };
      });
    },
  },

  methods: {
    // Extension urls are keyed by the *Extension definition's* id, not the
    // FSH slice name — try every candidate given.
    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    refId(ref) {
      if (!ref) return null;
      return ref.includes("/") ? ref.split("/")[1] : ref;
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "N/A";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved") return "done";
      if (status === "rejected") return "error";
      if (status === "cancelled") return "none";
      if (status && status.includes("review")) return "active";
      return "warn";
    },

    async loadTransfer() {
      const response = await fetch(`/fhir/Basic/${this.transferId}`);
      if (!response.ok) throw new Error("Transfer request not found");
      const resource = await response.json();
      if (!resource.meta?.profile?.includes(TRANSFER_PROFILE)) {
        throw new Error("Resource is not a HOD recommended transfer");
      }

      const statusCoding = this.getExt(resource, ["request-status", "status"])
        ?.valueCoding;

      this.transfer = {
        plannedTransferDate: this.getExt(resource, "planned-transfer-date")
          ?.valueDate,
        transferReason: this.getExt(resource, ["reason", "transfer-reason"])
          ?.valueString,
        status: statusCoding?.code || null,
        statusDisplay: statusCoding?.display || "Pending",
        eventDate:
          this.getExt(resource, "event-date")?.valueDate ||
          resource.meta?.lastUpdated,
        // Unlike eventDate (which is the *original submission* date and
        // never changes), this reflects whenever the resource was last
        // modified — used as the "applied on" date for the HOD Director
        // stage, since nothing in the review/apply chain updates event-date.
        lastUpdated: resource.meta?.lastUpdated,
        // Who originally submitted this recommendation ("Person/<id>") —
        // used by hod-apply-transfer.vue to confirm only the requesting
        // HOD Director can effect the transfer once PS has approved it.
        requesterUserRef: this.getExt(resource, "user-reference")
          ?.valueReference?.reference,
        // Must be declared here (even empty) so Vue 2 observes it as a
        // reactive key up front — loadRequester() fills it in later, and a
        // property added after the fact to an already-observed object
        // wouldn't trigger a re-render.
        requesterName: "",
      };

      this.staffPractitionerRef = this.getExt(resource, [
        "ihris-practitioner-reference",
        "practitioner",
      ])?.valueReference?.reference;

      const curExt = this.getExt(resource, [
        "position-reference",
        "current-position",
      ]);
      const destExt = this.getExt(resource, [
        "destination-position",
        "destition-position",
        "destination",
      ]);
      const curRef = curExt?.valueReference?.reference;
      const destRef = destExt?.valueReference?.reference;

      await Promise.all([
        this.loadPractitioner(),
        this.loadPosition(
          curRef,
          "currentPosition",
          curExt?.valueReference?.display,
        ),
        this.loadPosition(
          destRef,
          "destinationPosition",
          destExt?.valueReference?.display,
        ),
        this.loadRequester(this.transfer.requesterUserRef),
      ]);
    },

    // Resolves the HOD Director who submitted this recommendation.
    // requesterUserRef is a "Person/<id>" reference (a user account), and
    // Person can't be read directly from the browser — it carries the
    // ihris-password extension, so self-service roles are denied read on it.
    // This backend endpoint follows Person's ihris-practitioner-reference
    // server-side and returns just the linked Practitioner's name.
    async loadRequester(ref) {
      if (!ref) return;
      try {
        const id = this.refId(ref);
        const res = await fetch(`/site/general/getPersonPractitioner/${id}`);
        if (!res.ok) throw new Error("HTTP " + res.status);
        const data = await res.json();
        this.transfer.requesterName = data.name || "";
      } catch (err) {
        console.error("loadRequester error:", err);
      }
    },

    async loadPractitioner() {
      if (!this.staffPractitionerRef) return;
      try {
        const id = this.refId(this.staffPractitionerRef);
        const response = await fetch(`/fhir/Practitioner/${id}?_elements=name`);
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.staffName = name
          ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading staff practitioner:", error);
        this.staffName = "Unknown";
      }
    },

    // Walk Location.partOf up the hierarchy (facility → council → district)
    // until a Location tagged with the district profile is found.
    async resolveDistrict(facilityRef) {
      try {
        let ref = facilityRef;
        for (let i = 0; i < 5 && ref; i++) {
          const id = this.refId(ref);
          if (!id) return "";
          const res = await fetch(`/fhir/Location/${id}`);
          if (!res.ok) return "";
          const loc = await res.json();
          if (loc.meta?.profile?.some((p) => p.includes("ls-district"))) {
            return loc.name || "";
          }
          ref = loc.partOf?.reference;
        }
        return "";
      } catch (error) {
        console.error("Error resolving district:", error);
        return "";
      }
    },

    async loadPosition(ref, target, fallbackDisplay) {
      // Seed with whatever the reference's own display carries, so the UI
      // shows *something* even if the deeper Basic/Location lookups below
      // fail (missing/unreachable resource, stale reference, etc.).
      this[target] = { designation: fallbackDisplay || "", loadError: null };
      if (!ref) return;

      try {
        const id = this.refId(ref);
        if (!id) return;
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) {
          console.error(
            `loadPosition: GET /fhir/Basic/${id} (${ref}) → HTTP ${response.status}`,
          );
          this[target] = {
            ...this[target],
            loadError: `Could not load position ${ref} (HTTP ${response.status})`,
          };
          return;
        }
        const position = await response.json();
        if (!position.extension?.length) {
          this[target] = {
            ...this[target],
            loadError: `${ref} has no position data on it`,
          };
          return;
        }
        const getExt = (part, type) =>
          position.extension?.find((e) => e.url.includes(part))?.[type];

        let designation = fallbackDisplay || "";
        const designationRef = getExt("designation", "valueReference")
          ?.reference;
        if (designationRef) {
          try {
            const dRes = await fetch(
              `/fhir/Basic/${this.refId(designationRef)}`,
            );
            const dData = await dRes.json();
            designation =
              dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || designation;
          } catch {
            // best-effort
          }
        }

        let facility = "";
        let district = "";
        const facilityRef = getExt("facility", "valueReference")?.reference;
        if (facilityRef) {
          try {
            const fRes = await fetch(
              `/fhir/Location/${this.refId(facilityRef)}`,
            );
            const fData = await fRes.json();
            facility = fData.name || "";
          } catch {
            // best-effort
          }
          district = await this.resolveDistrict(facilityRef);
        }

        let grade = "";
        const gradeRef = getExt("salary-grade", "valueReference")?.reference;
        if (gradeRef) {
          try {
            const gRes = await fetch(`/fhir/Basic/${this.refId(gradeRef)}`);
            const gData = await gRes.json();
            grade =
              gData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || "";
          } catch {
            // best-effort
          }
        }

        const maxPosts = getExt("maximum-practitioners", "valueInteger") || 0;
        let filled = 0;
        try {
          const countRes = await fetch(
            `/fhir/PractitionerRole?roleposition=Basic/${id}&active=true&_summary=count`,
          );
          const countData = await countRes.json();
          filled = countData.total || 0;
        } catch {
          // best-effort
        }

        this[target] = {
          designation,
          department: getExt("department", "valueCoding")?.display || "",
          facility,
          facilityId: facilityRef ? this.refId(facilityRef) : "",
          district,
          grade,
          maxPosts,
          vacant: Math.max(0, maxPosts - filled),
        };
      } catch (error) {
        console.error("Error loading position:", error);
      }
    },

    async loadReviews() {
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${REVIEW_PROFILE}&hodrecommendedtransfer=Basic/${this.transferId}&_count=50`,
        );
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);

        const reviewerRefs = [
          ...new Set(
            resources
              .map(
                (r) =>
                  this.getExt(r, [
                    "ihris-practitioner-reference",
                    "practitioner",
                  ])?.valueReference?.reference,
              )
              .filter(Boolean),
          ),
        ];
        const nameMap = {};
        await Promise.all(
          reviewerRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        this.reviews = resources.map((r) => {
          const reviewerRef = this.getExt(r, [
            "ihris-practitioner-reference",
            "practitioner",
          ])?.valueReference?.reference;
          const statusCoding = this.getExt(r, ["review-status", "status"])
            ?.valueCoding;
          return {
            id: r.id,
            reviewerCode: this.getExt(r, "reviewer")?.valueCoding?.code,
            reviewerName: nameMap[reviewerRef] || "Unknown",
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            comments: this.getExt(r, "comments")?.valueString || "",
            date: this.getExt(r, ["date", "event-date"])?.valueDate,
          };
        });
      } catch (error) {
        console.error("Error loading reviews:", error);
      }
    },

    async checkAccess() {
      this.checkingAccess = true;
      try {
        this.isAuthorized = await this.stageConfig.checkAuthorized(this);
      } catch (error) {
        console.error("checkAccess error:", error);
        this.isAuthorized = false;
      } finally {
        this.checkingAccess = false;
      }
    },

    async submitReview() {
      this.formSubmitted = true;
      if (
        !this.form.status ||
        !this.form.comments ||
        !this.form.comments.trim()
      ) {
        this.showSnackbar(
          "Please select a decision and add comments.",
          "error",
        );
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          // Named "reviewDecision", not "status" — processFHIR() always
          // sets this.fhir.status = "completed" for the FHIR resource's
          // own status, which would otherwise clobber this value.
          reviewDecision: this.form.status,
          comments: this.form.comments,
          date: this.form.date,
          request: this.transferId,
        };
        this.$route.query.request = this.transferId;
        this.afterSaveMessage = `${this.stageConfig.label} review submitted successfully!`;
        await this.processFHIR();
        this.showSnackbar(this.afterSaveMessage, "success");
        setTimeout(() => this.goBack(), 300);
      } catch (error) {
        console.error("submitReview error:", error);
        this.showSnackbar(
          "Failed to submit review. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },
  },

  async mounted() {
    await this.$nextTick();

    // Wait for generalMixin to finish loading loggedInStaff
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    this.transferId = this.queries?.request;
    if (!this.transferId) {
      this.error = "No transfer request specified.";
      this.loading = false;
      return;
    }

    try {
      await this.loadTransfer();
      await Promise.all([this.checkAccess(), this.loadReviews()]);
    } catch (error) {
      console.error("Error loading transfer review:", error);
      this.error = error.message || "Failed to load this transfer request";
    } finally {
      this.loading = false;
    }
  },
};
